def normalize_historical_evidence(strategy_id,symbol,family,regime,records=None,config=None):
    rows=records or [];cfg=config or {};n=len(rows);early=int(cfg.get("minimum_early_samples",30));moderate=int(cfg.get("minimum_moderate_samples",100));strong=int(cfg.get("minimum_stronger_samples",250));label="stronger" if n>=strong else "moderate" if n>=moderate else "early" if n>=early else "insufficient";rs=[float(row.get("r",0)) for row in rows];average=sum(rs)/n if n else None;wins=sum(value>0 for value in rs)/n if n else None
    return {"strategy_id":strategy_id,"symbol":symbol,"family":family,"regime":regime,"sample_size":n,"evidence_label":label,"average_r":average,"profit_factor":None,"maximum_drawdown_r":None,"win_rate":wins,"out_of_sample_average_r":None,"walk_forward_stability":None,"eligible_for_ranking":label in {"moderate","stronger"} and bool(rows and all(row.get("out_of_sample",False) for row in rows)),"score":max(0,min(1,.5+(average or 0)*.1))}
